The title basically speaks for itself. See the following code when serveStatic is called with a non-existing file-path:
```ts
export const serveStatic = (options: ServeStaticOptions = { root: '' }) => {
  return async (c: Context, next: Next) => {
    // Do nothing if Response is already set
    if (c.finalized) {
      await next()
    }

    const url = new URL(c.req.url)

    let path = getFilePath({
      filename: options.path ?? url.pathname,
      root: options.root,
      defaultDocument: DEFAULT_DOCUMENT,
    })

    path = `./${path}`

    let content

    try {
      content = await Deno.readFile(path)
    } catch (e) {
      console.warn(`${e}`) // <-- Triggers with NotFound: No such file or directory (os error 2)
      await next() // <-- This triggers the flow of all the next middleware, which eventually completes
    }

    if (content) {
      const mimeType = getMimeType(path)
      if (mimeType) {
        c.header('Content-Type', mimeType)
      }
      // Return Response object
      return c.body(content)
    } else {
      console.warn(`Static file: ${path} is not found`) // <-- Then this is logged
      await next() // And next is called again without a middleware in the queue and thus errors
    }
    return
  }
}
```

Proposed fix: Remove the await next() call from this part:
```ts
